use crate::model::Summary;

pub fn run(data: &[u8], limit: i64) -> Summary {
    let mut summary = Summary { frames: Vec::new(), consumed: 0, error: 0 };
    let mut offset = 0;

    while offset < data.len() {
        let length = data[offset] as usize;
        if length as i64 > limit {
            summary.error = 3;
            return summary;
        }

        let payload_start = offset + 1;
        let checksum_offset = payload_start + length;
        if checksum_offset >= data.len() {
            summary.error = 1;
            return summary;
        }

        let payload = &data[payload_start..checksum_offset];
        let checksum = payload.iter().fold(0u8, |sum, &byte| sum.wrapping_add(byte));
        if checksum != data[checksum_offset] {
            summary.error = 2;
            return summary;
        }

        summary.frames.push(payload.to_vec());
        offset = checksum_offset + 1;
        summary.consumed = offset as i64;
    }

    summary
}

